-- MUST return 0 before import. This generator cannot inspect your live database.
SELECT COUNT(*) AS collision_count
FROM `item_template`
WHERE (`entry` BETWEEN 200000 AND 200999 OR `entry` BETWEEN 220000 AND 220999 OR `entry` BETWEEN 240000 AND 240999 OR `entry` BETWEEN 260000 AND 260999 OR `entry` BETWEEN 280000 AND 280999 OR `entry` BETWEEN 300000 AND 300999 OR `entry` BETWEEN 320000 AND 320999 OR `entry` BETWEEN 340000 AND 340999 OR `entry` BETWEEN 360000 AND 360999 OR `entry` BETWEEN 380000 AND 380999);

-- If non-zero, inspect collisions before importing:
SELECT `entry`,`name` FROM `item_template`
WHERE (`entry` BETWEEN 200000 AND 200999 OR `entry` BETWEEN 220000 AND 220999 OR `entry` BETWEEN 240000 AND 240999 OR `entry` BETWEEN 260000 AND 260999 OR `entry` BETWEEN 280000 AND 280999 OR `entry` BETWEEN 300000 AND 300999 OR `entry` BETWEEN 320000 AND 320999 OR `entry` BETWEEN 340000 AND 340999 OR `entry` BETWEEN 360000 AND 360999 OR `entry` BETWEEN 380000 AND 380999)
ORDER BY `entry`;

SELECT COUNT(*) AS generated_loot_pool_collision_count
FROM `reference_loot_template`
WHERE `Entry` IN (3000000, 3000001, 3000002, 3000003, 3000004, 3000005);
SELECT `Entry`,`Item`,`Reference`,`Comment` FROM `reference_loot_template`
WHERE `Entry` IN (3000000, 3000001, 3000002, 3000003, 3000004, 3000005)
ORDER BY `Entry`,`Item`;

SELECT COUNT(*) AS generated_loot_reference_collision_count
FROM `reference_loot_template`
WHERE `Reference` IN (3000000, 3000001, 3000002, 3000003, 3000004, 3000005);
SELECT `Entry`,`Item`,`Reference`,`Comment` FROM `reference_loot_template`
WHERE `Reference` IN (3000000, 3000001, 3000002, 3000003, 3000004, 3000005)
ORDER BY `Entry`,`Item`;

